steps.codeExample:
from collections import deque

grafo = {"A": ["B", "C"], "B": ["D"], "C": [], "D": []}
fila = deque(["A"])
visitados = {"A"}

while fila:
    atual = fila.popleft()
    for vizinho in grafo[atual]:
        if vizinho not in visitados:
            visitados.add(vizinho)
            fila.append(vizinho)

